// Data access shared by C Comparar and D Replanejar: stored hourly series (web/data, via core/data.js) and the API.
// Every metric carries its own seal (from the origin's state) and source; a missing value stays null.
// Source of truth: this .ts file. scenario-data.js is generated by `npm --prefix web run build:ts`.
import { loadSeries, sealFor, api } from "../core/data.js";
import type { SiteSeriesLike, SitesDoc, Seal } from "../core/data.js";
// @ts-ignore TS7016: JS module without types
import { HOUR_MS } from "../../lab/data.js";
export { HOUR_MS };

/** Metrics of a window, from the stored series ("static") or from the API ("api"). */
export interface ScenarioMetrics {
  dark: number | null; blackout: number | null; sunPct: number | null; earthPct: number | null; bothPct: number | null;
  seal: Seal; status: string | null; origin: "static" | "api"; src: string; sha: string | null | undefined;
}
/** Raw metrics block of POST /api/compare and POST /api/scenarios/delay. */
interface ApiMetricsBlock {
  longest_continuous_dark_hours?: unknown; longest_continuous_comm_gap_hours?: unknown; sun_visible_fraction?: unknown;
  earth_visible_fraction?: unknown; simultaneous_fraction?: unknown;
}
interface CompareResponse { results?: { data_status?: string; science_status?: string; evaluation?: { metrics?: ApiMetricsBlock }; site?: { series_sha256?: string } }[]; }
interface DelayOption { kind?: string; site_id?: string; distance_km?: number; data_status?: string; admissible?: boolean; reason?: string; science_status?: string; delay_hours?: number; metrics?: ApiMetricsBlock }
interface DelayResponse { options?: DelayOption[]; }
export interface Nearby { siteId: string | undefined; km: number | null; available: boolean; admissible: boolean | null; reason: string | undefined; status: string | null; }

export async function loadAll(doc: Pick<SitesDoc, "sites">): Promise<Map<string, SiteSeriesLike>> {
  const m = new Map<string, SiteSeriesLike>();
  await Promise.all(doc.sites.map(async s => m.set(s.id, await loadSeries(s))));
  return m;
}

/** Metrics of [startMs, +hours) from the stored series; null when the window is outside the computed range. */
export function staticMetrics(series: SiteSeriesLike, startMs: number, hours: number, status: string, siteId = ""): ScenarioMetrics | null {
  const w = series.window(startMs, hours);
  if (w.status !== "COMPUTED") return null;
  return { dark: w.longestDarkH, blackout: w.longestBlackoutH, sunPct: w.sunPct, earthPct: w.earthPct, bothPct: w.bothPct as number | null,
    seal: sealFor(status), status, origin: "static", src: `web/data/sites/${siteId || (series.meta as { site?: { id?: string } }).site?.id || ""}.bin`, sha: series.meta.series.sha256 };
}

/** Hourly booleans (Sun / Earth above the local horizon) for the window. */
export function flagsOf(series: SiteSeriesLike, startMs: number, hours: number): { sun: (boolean | null)[]; earth: (boolean | null)[] } {
  const i0 = Math.ceil((startMs - series.start) / HOUR_MS), sun: (boolean | null)[] = [], earth: (boolean | null)[] = [];
  for (let h = 0; h < hours; h++) {
    const i = i0 + h;
    if (i < 0 || i >= series.count) { sun.push(null); earth.push(null); continue; }
    sun.push(series.sunMargin[i] >= 0); earth.push(series.earthMargin[i] >= 0);
  }
  return { sun, earth };
}

/** API metrics → the same shape as staticMetrics. null unless the API returned numbers (data_status AVAILABLE). */
export function mapApiMetrics(m: ApiMetricsBlock | null | undefined, scienceStatus: string | undefined, src: string, sha: string | null = null): ScenarioMetrics | null {
  if (!m) return null;
  const p = (x: unknown): number | null => (typeof x === "number" && Number.isFinite(x) ? 100 * x : null);
  const n = (x: unknown): number | null => (typeof x === "number" && Number.isFinite(x) ? x : null);
  return { dark: n(m.longest_continuous_dark_hours), blackout: n(m.longest_continuous_comm_gap_hours), sunPct: p(m.sun_visible_fraction),
    earthPct: p(m.earth_visible_fraction), bothPct: p(m.simultaneous_fraction), seal: sealFor(scienceStatus), status: scienceStatus || null,
    origin: "api", src, sha };
}

const cache = new Map<string, Promise<unknown>>();
// Keep only in-flight requests; a transient error must not be cached forever.
const once = <T>(key: string, fn: () => Promise<T>): Promise<T> => {
 if (!cache.has(key)) {
  const pending=Promise.resolve().then(fn).finally(()=>{if(cache.get(key)===pending)cache.delete(key);});
  cache.set(key,pending);
 }
 return cache.get(key) as Promise<T>;
};

/** POST /api/compare for one site. {online, metrics|null}. */
export function apiCompareMetrics(siteId: string, startIso: string, hours: number): Promise<{ online: boolean; metrics: ScenarioMetrics | null }> {
  return once(`c|${siteId}|${startIso}|${hours}`, async () => {
    const r = await api<CompareResponse>("/api/compare", { method: "POST", body: { site_ids: [siteId], start_utc: startIso, duration_hours: hours } });
    if (!r.ok) return { online: !r.offline, metrics: null };
    const x = r.data?.results?.[0];
    if (!x || x.data_status !== "AVAILABLE" || !x.evaluation?.metrics) return { online: true, metrics: null };
    return { online: true, metrics: mapApiMetrics(x.evaluation.metrics, x.science_status, "POST /api/compare", x.site?.series_sha256 || null) };
  });
}

/** POST /api/scenarios/delay. {online, base, delayed} (each null without numbers). */
export function apiDelayMetrics({ siteId, startIso, hours, delayH, rules }: { siteId: string; startIso: string; hours: number; delayH: number; rules: { night: number; blackout: number } }): Promise<{ online: boolean; base: ScenarioMetrics | null; delayed: ScenarioMetrics | null; nearby: Nearby[] }> {
  return once(`d|${siteId}|${startIso}|${hours}|${delayH}|${rules.night}|${rules.blackout}`, async () => {
    const r = await api<DelayResponse>("/api/scenarios/delay", { method: "POST", body: { site_id: siteId, start_utc: startIso, duration_hours: hours,
      delays_hours: [delayH], include_nearby: true, max_nearby: 3,
      constraints: { max_continuous_dark_hours: rules.night, max_continuous_comm_gap_hours: rules.blackout } } });
    if (!r.ok) return { online: !r.offline, base: null, delayed: null, nearby: [] };
    const pick = (o: DelayOption | undefined) => (o && o.data_status === "AVAILABLE" && o.metrics ? mapApiMetrics(o.metrics, o.science_status, "POST /api/scenarios/delay") : null);
    const opts = r.data?.options || [];
    // Nearby catalog sites the API evaluated at the delayed start (from the Polar Lab / onboard replan, now in v3).
    const nearby: Nearby[] = opts.filter(o => o.kind === "nearby_site").map(o => ({ siteId: o.site_id, km: o.distance_km ?? null,
      available: o.data_status === "AVAILABLE", admissible: o.data_status === "AVAILABLE" ? !!o.admissible : null, reason: o.reason || o.data_status, status: o.science_status || null }));
    return { online: true, base: pick(opts.find(o => o.kind === "baseline")), delayed: pick(opts.find(o => o.kind === "delay" && o.delay_hours === delayH)), nearby };
  });
}
